function banterFor(id) { const b = BANTER[id]; if (!b) return null; let best = null; for (const c in b) if (+c <= SAVE.ch) best = b[c]; return best; }
async function forceTalk(npcName) {
  for (;;) {
    const all = allRecs(), opts = all.map(r => ({ t: HEROES[r.id].n, c: r.dead ? COL.red : undefined }));
    const i = await menu(opts, { title: 'TALK TO', x: 160, y: 8, w: 150, rows: 12 }); if (i < 0) return;
    const r = all[i];
    if (r.dead) await say('(' + HEROES[r.id].n + ' IS DOWN. THE PRIEST CAN RAISE THEM.)', npcName);
    else await memberTalk(r.id);
  }
}

