// ================= the world keeps talking =================
// A "line" is a string or an array of strings said in order. "id>TEXT" is said by that force member, and only
// if they've joined and aren't down, so townsfolk get answered by whoever happens to be riding with you.
// Talking to someone again moves on to their next line instead of repeating. States key off SAVE.bi (battles
// won this chapter, 0-3): the latest state at or below it is used.
const memberHere = id => !!(SAVE.force[id] && !SAVE.force[id].dead);
function lineParts(line, who) { const out = []; for (const s of [].concat(line)) { const m = /^([a-z0-9]+)>(.*)$/.exec(s); if (!m) out.push([who, s]); else if (memberHere(m[1])) out.push([HEROES[m[1]].n, m[2]]); } return out; }
async function sayAll(line, who) { for (const [n, s] of lineParts(line, who)) await say(s, n); }
const HEARD = {}; // this session only: how far into each pool you've talked
function nextOf(key, pool) { const i = HEARD[key] || 0; HEARD[key] = i + 1; return pool[i % pool.length]; }
function stateOf(o) { let best = null; for (const k in o) if (+k <= SAVE.bi) best = o[k]; return best; }
function lastWon() { if (SAVE.flags.cleared) return 'b84'; const ch = CHAPTERS[SAVE.ch - 1]; if (SAVE.bi > 0) return ch.battles[SAVE.bi - 1]; const p = CHAPTERS[SAVE.ch - 2]; return p ? p.battles[p.battles.length - 1] : null; }

// ---------- the force: a fresh reaction to the battle just won, then the chapter line ----------
function memberPool(id) { const p = [(REACT[lastWon()] || {})[id], banterFor(id)].filter(Boolean); return p.length ? p : ['...']; }
async function memberTalk(id) { await sayAll(nextOf('m|' + id + '|' + SAVE.ch + '|' + SAVE.bi, memberPool(id)), HEROES[id].n); }

// ---------- townsfolk: their usual words (or the old TOWN_LATER line), then whatever's new since the last battle ----------
function townPool(town, name, base, room) {
  const T = (TALK[town] || {})[(room ? '@' : '') + name];
  return [(room ? null : laterLines(town, name)) || base, ...((T && stateOf(T)) || [])].filter(Boolean);
}
async function townTalk(n) { const pool = townPool(TV.id, n.name, n.a, TV.room); if (pool.length) await sayAll(nextOf(TV.id + '|' + (TV.room || '') + '|' + n.name + '|' + n.x + '|' + SAVE.bi, pool), n.name); }

// ---------- members idle in the streets between battles (the ones with something new to say first) ----------
function townMembers(T) {
  const R = REACT[lastWon()] || {}, seed = SAVE.ch * 31 + SAVE.bi * 7, h = s => [...s].reduce((a, c) => (a * 31 + c.charCodeAt(0)) % 9973, seed);
  const ids = Object.keys(SAVE.force).filter(id => id !== 'dax' && memberHere(id)).sort((a, b) => (!!R[b] - !!R[a]) || h(a) - h(b)).slice(0, 4);
  const taken = TV.npcs.map(n => [n.x, n.y]).concat([T.spawn]), D4 = [[1, 0], [-1, 0], [0, 1], [0, -1]], spots = [];
  for (let y = 1; y < TV.h - 1; y++) for (let x = 1; x < TV.w - 1; x++)
    if (standable(x, y) && x !== T.spawn[0] && TV.map[y - 1][x] !== 'd' && D4.filter(([dx, dy]) => standable(x + dx, y + dy)).length >= 3 && !taken.some(([a, b]) => Math.abs(a - x) + Math.abs(b - y) < 3)) spots.push([x, y]);
  const out = [];
  ids.forEach((id, i) => {
    const ok = spots.filter(([x, y]) => !out.some(o => Math.abs(o.x - x) + Math.abs(o.y - y) < 3)); if (!ok.length) return;
    const [x, y] = ok[(h(id) * 7 + i * 13) % ok.length], art = HEROES[id].art; artOf(art);
    out.push({ x, y, kind: 'member', id, name: HEROES[id].n, art, vis: () => true, face: (h(id) & 1) ? -1 : 1 });
  });
  return out;
}

// ---------- overheard: short lines over people's heads as you walk past ----------
function barkTick(cx, cy) {
  if (TV.room || WINS.length) return;
  const b = TV.bark;
  if (b) { if (--b.t > 0) { drawBark(b, cx, cy); return; } TV.bark = null; TV.barkWait = 100 + ((Math.random() * 160) | 0); }
  if (--TV.barkWait > 0) return;
  const near = n => n.art && n.vis() && Math.abs(n.x - TV.px) <= 9 && Math.abs(n.y - TV.py) <= 6, opts = [];
  for (const s of stateOf(BARKS[TV.id] || {}) || []) { const i = s.indexOf(':'), n = TV.npcs.find(m => m.name === s.slice(0, i) && near(m)); if (n) opts.push([n, s.slice(i + 1)]); }
  for (const n of TV.npcs) if (n.kind === 'member' && near(n)) for (const s of MEMBER_BARK[n.id] || []) opts.push([n, s]);
  const fresh = opts.filter(o => o[1] !== TV.lastBark); if (!fresh.length) { TV.barkWait = 60; return; }
  const [n, s] = fresh[(Math.random() * fresh.length) | 0]; TV.lastBark = s; TV.bark = { n, ls: wrapT(s, 22), t: 150 };
}
function drawBark(b, cx, cy) {
  const w = Math.max(...b.ls.map(l => l.length)) * 6 + 10, h = b.ls.length * 10 + 6, nx = b.n.x * 16 - cx + 8;
  const x = clamp(nx - (w >> 1), 2, W - w - 2), y = Math.max(22, b.n.y * 16 - cy - 14 - h);
  panel(x, y, w, h); rectF(clamp(nx - 1, x + 3, x + w - 6), y + h, 3, 3, UI.text); b.ls.forEach((l, i) => text(l, x + 5, y + 4 + i * 10, UI.text));
}

