    '@IRON WIDOW': { 2: ["GREYMANE CARRIED MY HUSBAND'S FRAME OUT OF THE FIRE. I'M GOING TO THANK HIM. I'M WORKING UP TO IT. IT MIGHT TAKE A YEAR."] },
